UPDATE normal_group_creation_item_member


    SET creator_save_command_id = #{commandId},
        creator_saved_member_status = 'PENDING',


    SET member_save_command_id = #{commandId},
        member_saved_creator_status = 'PENDING',


    updated_at = #{now}
WHERE id = #{memberId}


    AND creator_saved_member_status = #{expectedStatus}


    AND member_saved_creator_status = #{expectedStatus}

UPDATE normal_group_creation_item_member


    SET creator_saved_member_status = #{status},


    SET member_saved_creator_status = #{status},


    last_error_code = #{errorCode}, last_error_message = #{errorMessage}, updated_at = #{now}
WHERE id = #{memberId}


    AND creator_save_command_id = #{commandId}
    AND creator_saved_member_status = 'PENDING'


    AND member_save_command_id = #{commandId}
    AND member_saved_creator_status = 'PENDING'

