SELECT COALESCE(SUM(
  (CASE WHEN creator_saved_member_status = 'SUCCESS' THEN 0 ELSE 1 END) +
  (CASE WHEN member_saved_creator_status = 'SUCCESS' THEN 0 ELSE 1 END)
), 0)
FROM normal_group_creation_item_member
WHERE item_id = #{itemId}

